UPDATE lessons SET title='Year 3, Week 6, Lesson 1: Text features: headings, glossary and index', data=json_patch(data,'{"child_mission":"Use headings, glossaries and indexes to locate and understand information.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Keep the independent response and two written check responses; record oral retelling or performance where required by the task.","explicit_teaching":null,"extension":"Create a new example using a completely different character or setting, show the same skill, then explain to another person how you checked its accuracy.","follow_up_challenges":null,"guided_practice":"WE DO — attempt each prompt before comparing to the feedback.\n1. Which heading would likely help you find where koalas live: Food, Habitat or Glossary?\nCOMPARE: Habitat. Food would more likely discuss diet.\n2. Which feature helps most when you need the meaning of invertebrate?\nCOMPARE: A glossary definition. An index points to pages, not definitions.\n3. Would an index or a glossary better help you find every page that mentions claws?\nCOMPARE: An index lists page references; a glossary explains meanings.\n4. For each need, name the best feature: define burrow; find pages about diet; jump to a Shelter section.\nCOMPARE: Glossary; index; heading/contents.","hoard_words":null,"independent_task":"YOU DO — complete the following substantial original task, not a copied model.\nCreate a two-page mini-information text about a local animal with two headings, four glossary definitions and a short alphabetised index. Explain when a reader would use each feature.","interactive_activities":null,"learning_area":"English","learning_intention":"Use headings, glossaries and indexes to locate and understand information.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typing area","Pencil for optional evidence"],"offline_alternative":"Use paper to copy only the original independent prompt; have the child respond in writing or orally as required. Save a photograph or brief parent observation for the learning record.","outcome_codes":["EN2-RECOM-01"],"parent_notes":"Parent: Marking guidance: Require working examples of each feature and a clear explanation of purpose. Facts should be plausible and checkable. Accept plausible original solutions where the text supports them; require the learner to explain at least one independent choice.\n\nParent: Written model 1: Original demonstration: To learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page.\n\nParent: Written model 2: Common error: Indexes help location; they do not rewrite the information for you. Correction: An index lists page references; a glossary explains meanings.\n\nParent: Assess comprehension and language rather than penalising speech or motor difficulties unrelated to the objective. Keep written models out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"Headings group information so a reader can jump to the needed part. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["Headings group information so a reader can jump to the needed part.","A heading organises ideas; it does not prove every sentence under it is accurate.","Ignore the words and invent a more exciting event.","Copy the model word-for-word and call that independent work."],"question":"Which idea is taught in the stage \"Scan headings to find a section\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"A glossary defines important subject words, usually near the end of an information text. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["A glossary defines important subject words, usually near the end of an information text.","Guessing a technical word without checking can create a false fact.","Copy the model word-for-word and call that independent work.","Treat a missing detail as a stated fact."],"question":"Which idea is taught in the stage \"Use a glossary for word meanings\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"An index lists topics alphabetically with page numbers so you can find where a word appears. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["An index lists topics alphabetically with page numbers so you can find where a word appears.","Indexes help location; they do not rewrite the information for you.","Treat a missing detail as a stated fact.","Skip the prompt because the first idea sounded good."],"question":"Which idea is taught in the stage \"Use an index to find page references\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Match the question to the feature: meaning, location or section overview. The other choices either name a known misunderstanding or avoid explaining the actual strategy.","options":["Match the question to the feature: meaning, location or section overview.","Using the wrong feature wastes time and may miss the answer.","Skip the prompt because the first idea sounded good.","Ignore the words and invent a more exciting event."],"question":"Which idea is taught in the stage \"Choose the right feature for the job\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Habitat. Food would more likely discuss diet. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["Habitat. Food would more likely discuss diet.","A heading organises ideas; it does not prove every sentence under it is accurate.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Which heading would likely help you find where koalas live: Food, Habitat or Glo\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"A glossary definition. An index points to pages, not definitions. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["A glossary definition. An index points to pages, not definitions.","Guessing a technical word without checking can create a false fact.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Which feature helps most when you need the meaning of invertebrate?\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"An index lists page references; a glossary explains meanings. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["An index lists page references; a glossary explains meanings.","Indexes help location; they do not rewrite the information for you.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Would an index or a glossary better help you find every page that mentions claws\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"Glossary; index; heading/contents. This explanation uses the original evidence or language point, rather than treating a misconception as the correct response.","options":["Glossary; index; heading/contents.","Using the wrong feature wastes time and may miss the answer.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"For each need, name the best feature: define burrow; find pages about diet; jump\", which feedback is most useful?","type":"multiple_choice"},{"explanation":"Meaningful understanding is shown when a learner transfers the method to new text or speech and explains their evidence.","marking_guide":"Require an original relevant example, accurate terminology and an explanation grounded in the example.","question":"Use your own example to demonstrate heading and explain the evidence supporting your choice.","sample_answer":"Original demonstration: To learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page.","type":"short_answer"},{"explanation":"Explaining a correction helps the learner distinguish an effective strategy from a plausible-sounding but inaccurate approach.","marking_guide":"Require a genuine relevant error, accurate correction and a reason that refers to the target concept.","question":"Identify and correct a common mistake relating to index in this lesson.","sample_answer":"Common error: Indexes help location; they do not rewrite the information for you. Correction: An index lists page references; a glossary explains meanings.","type":"short_answer"}],"resources":null,"response_prompt":"Submit your original independent work and your brief explanation of the key choices you made.","review_status":"unreviewed","seed_key":"s2-eng-y3-w06-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; compare the existing Coming Soon card and official syllabus content points before marking verified.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise heading.","Read the mission before you start writing or speaking.","Your goal is: Use headings, glossaries and indexes to locate and understand information."],"guided":["Attempt each guided prompt without looking ahead.","Compare your attempt with the supplied specific feedback.","Guided comparison: A glossary definition. An index points to pages, not definitions."],"learn":["Study the first worked demonstration carefully.","Name the exact words or events that make it work.","Demonstration: To learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page."],"quiz":["Read the whole question and eliminate misconceptions.","Prefer the option that quotes or uses actual evidence.","Likely trap: Indexes help location; they do not rewrite the information for you."],"submit":["Include your own response and a short reason.","Proofread names, sequence and punctuation before sending.","Success looks like: Use headings, glossaries and indexes to locate and understand information."],"teach0":["Focus on scan headings to find a section.","Hold this teaching point: Headings group information so a reader can jump to the needed part.","Worked comparison: Habitat. Food would more likely discuss diet."],"teach1":["Focus on use a glossary for word meanings.","Hold this teaching point: A glossary defines important subject words, usually near the end of an information text.","Worked comparison: A glossary definition. An index points to pages, not definitions."],"teach2":["Focus on use an index to find page references.","Hold this teaching point: An index lists topics alphabetically with page numbers so you can find where a word appears.","Worked comparison: An index lists page references; a glossary explains meanings."],"teach3":["Focus on choose the right feature for the job.","Hold this teaching point: Match the question to the feature: meaning, location or section overview.","Worked comparison: Glossary; index; heading/contents."],"write":["Use the independent instructions, not the model words.","Give an original response and the reason behind it.","Independent reminder: Create a two-page mini-information text about a local animal with two headings, four glossary definitions and a short alphabetised index. Explain when a reader "]},"subject":"English","success_criteria":["I can use heading with a specific example from this lesson.","I can identify glossary and point to the words or events that support it.","I can practise index independently on a new prompt.","I can notice feature needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying heading independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to scan headings to find a section?","type":"multiple_choice"},"example":"WATCH MY THINKING\nTo learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page.\n\nYOUR SMALL TRY\nWhich heading would likely help you find where koalas live: Food, Habitat or Glossary?\n\nCOMPARE AND CORRECT\nHabitat. Food would more likely discuss diet.","explain":"Headings group information so a reader can jump to the needed part.\n\nHeadings group information so a reader can jump to the needed part. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nA heading organises ideas; it does not prove every sentence under it is accurate. Re-read the prompt and correct the misunderstanding before moving on.","title":"Scan headings to find a section","visual":[{"alt":"Heading Feeding beside a glossary definition for invertebrate.","caption":"Headings locate sections; glossaries explain words.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Heading</text><text x=\"28\" y=\"78\">Feeding</text><text x=\"358\" y=\"42\">Glossary</text><text x=\"358\" y=\"78\">invertebrate = ...</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I read the first example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or events that carry the meaning before you copy a conclusion.","who":"juno"},{"text":"So I should try the small prompt myself, then compare it with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: To learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page. Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I read the first example, but I am not sure which detail matters most.\nJuno: Name the exact words or events that carry the meaning before you copy a conclusion.\nPip: So I should try the small prompt myself, then compare it with the feedback.\nJuno: Pause here. Use this model: To learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page. Then write your own attempt."}}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying glossary independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to use a glossary for word meanings?","type":"multiple_choice"},"example":"WATCH MY THINKING\nIf I know the word habitat appears but not its meaning, the glossary can define it.\n\nYOUR SMALL TRY\nWhich feature helps most when you need the meaning of invertebrate?\n\nCOMPARE AND CORRECT\nA glossary definition. An index points to pages, not definitions.","explain":"A glossary defines important subject words, usually near the end of an information text.\n\nA glossary defines important subject words, usually near the end of an information text. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nGuessing a technical word without checking can create a false fact. Re-read the prompt and correct the misunderstanding before moving on.","title":"Use a glossary for word meanings","visual":[{"alt":"Index entry echidna with page numbers for locating information.","caption":"An index points to pages; it does not define the word.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Index</text><text x=\"28\" y=\"78\">echidna 4, 9</text><text x=\"358\" y=\"42\">Purpose</text><text x=\"358\" y=\"78\">find page numbers</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying index independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to use an index to find page references?","type":"multiple_choice"},"example":"WATCH MY THINKING\nI look up echidna in the index to find the pages that mention it, then read those sections.\n\nYOUR SMALL TRY\nWould an index or a glossary better help you find every page that mentions claws?\n\nCOMPARE AND CORRECT\nAn index lists page references; a glossary explains meanings.","explain":"An index lists topics alphabetically with page numbers so you can find where a word appears.\n\nAn index lists topics alphabetically with page numbers so you can find where a word appears. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nIndexes help location; they do not rewrite the information for you. Re-read the prompt and correct the misunderstanding before moving on.","title":"Use an index to find page references"},{"check":{"correct_index":0,"explanation":"The best approach uses the specific concept, evidence and reasoning before practising independently; copying or inventing unsupported facts does not show understanding.","options":["Use the example and explain the clue or language choice before trying feature independently.","Copy every sentence exactly without explaining it.","Add a made-up event and describe it as a fact.","Ignore the task and choose an unrelated detail."],"question":"Which is the strongest next step when learning to choose the right feature for the job?","type":"multiple_choice"},"example":"WATCH MY THINKING\nMeaning → glossary. Page finding → index. Section topic → heading or contents.\n\nYOUR SMALL TRY\nFor each need, name the best feature: define burrow; find pages about diet; jump to a Shelter section.\n\nCOMPARE AND CORRECT\nGlossary; index; heading/contents.","explain":"Match the question to the feature: meaning, location or section overview.\n\nMatch the question to the feature: meaning, location or section overview. This matters because a reader or listener can only understand your ideas when you notice how the language works, test your understanding on specific examples and explain the evidence for your choice. Keep the meaning of the original text rather than changing facts to make an answer sound impressive. Read the model closely: which particular word, event or detail changes the meaning? Try explaining the same decision to someone else without repeating the model sentence. Then compare your new attempt with the feedback and revise anything that does not fit the actual evidence.","icon":"📖","notice":"WATCH OUT\nUsing the wrong feature wastes time and may miss the answer. Re-read the prompt and correct the misunderstanding before moving on.","title":"Choose the right feature for the job"}],"title":"Year 3, Week 6, Lesson 1: Text features: headings, glossary and index","unit_number":2,"unit_title":"Information reports","week":6,"week_in_unit":1,"word_challenges":null,"worked_example":"I DO — To learn about echidna food, I scan for a heading such as \"Feeding\" before reading every page.\n\nNow look for the exact evidence in the words or actions. If I know the word habitat appears but not its meaning, the glossary can define it.","worked_visuals":[{"alt":"Heading Feeding beside a glossary definition for invertebrate.","caption":"Headings locate sections; glossaries explain words.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Heading</text><text x=\"28\" y=\"78\">Feeding</text><text x=\"358\" y=\"42\">Glossary</text><text x=\"358\" y=\"78\">invertebrate = ...</text></g></svg>"},{"alt":"Index entry echidna with page numbers for locating information.","caption":"An index points to pages; it does not define the word.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Index</text><text x=\"28\" y=\"78\">echidna 4, 9</text><text x=\"358\" y=\"42\">Purpose</text><text x=\"358\" y=\"78\">find page numbers</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w06-l1' AND family_id IS NULL;
